"""
tests/unit/agents/test_diagnostic_agent.py
───────────────────────────────────────────
Unit tests for the Diagnostic Agent — Day 1.
These tests use the rule-based fallback path so NO OpenAI key is required.
"""

import pytest
from datadoctor.tools.log_parser import parse_error_log
from datadoctor.tools.schema_diff import diff_schemas
from datadoctor.agents.diagnostic_agent import _rule_based_fallback


# ── Sample error logs (generated by simulate_failure.py) ──────────────────────

SCHEMA_DRIFT_LOG = """SchemaValidationError: Column(s) missing from incoming batch.
  Expected : ['amount', 'customer_id', 'order_date', 'order_id', 'postal_code', 'status']
  Received : ['amount', 'customer_id', 'order_date', 'order_id', 'status', 'zip_code']
  Missing  : ['postal_code']
  Extra    : ['zip_code']
Traceback (most recent call last):
  File 'pipeline/loaders/orders_loader.py', line 84, in validate_schema
    raise SchemaValidationError(f'Missing columns: {missing}')
SchemaValidationError: Missing columns: ['postal_code']"""

DATE_FORMAT_LOG = """FormatParsingError: Could not parse 'order_date' column.
  Expected format : YYYY-MM-DD
  Sample values   : ['18-01-2024', '19-01-2024']
Traceback (most recent call last):
  File 'pipeline/transformers/date_normalizer.py', line 42, in parse_dates
    df['order_date'] = pd.to_datetime(df['order_date'], format='%Y-%m-%d')
  File 'pandas/core/tools/datetimes.py', line 1067, in to_datetime
ValueError: time data '18-01-2024' does not match format '%Y-%m-%d'"""


# ── log_parser tests ──────────────────────────────────────────────────────────

class TestLogParser:

    def test_schema_drift_detection(self):
        result = parse_error_log(SCHEMA_DRIFT_LOG)
        assert result["error_type"] == "SCHEMA_DRIFT"
        assert "postal_code" in result["missing_columns"]
        assert "zip_code" in result["extra_columns"]

    def test_date_format_detection(self):
        result = parse_error_log(DATE_FORMAT_LOG)
        assert result["error_type"] == "FORMAT_ENCODING"
        assert result["bad_column"] == "order_date"

    def test_unknown_error(self):
        result = parse_error_log("Some random unrecognised error occurred")
        assert result["error_type"] == "UNKNOWN"

    def test_raw_exception_captured(self):
        result = parse_error_log(SCHEMA_DRIFT_LOG)
        assert "SchemaValidationError" in result["raw_exception"]


# ── schema_diff tests ─────────────────────────────────────────────────────────

class TestSchemaDiff:

    def test_rename_candidate_detected(self):
        # Simulate: pipeline expects postal_code, incoming has zip_code
        result = diff_schemas(
            pipeline_name="orders_daily_loader",
            incoming_columns=["order_id", "customer_id", "zip_code", "amount", "order_date", "status"],
        )
        # Without DB, expected_schema is empty → rename_candidates may be empty
        # But missing and extra should reflect the diff against empty schema
        assert isinstance(result["missing_columns"], list)
        assert isinstance(result["extra_columns"], list)
        assert isinstance(result["rename_candidates"], list)

    def test_matched_columns(self):
        result = diff_schemas(
            pipeline_name="orders_daily_loader",
            incoming_columns=["order_id", "customer_id", "postal_code", "amount", "order_date", "status"],
        )
        assert isinstance(result["matched_columns"], list)


# ── rule-based fallback tests ──────────────────────────────────────────────────

class TestRuleBasedFallback:

    def test_schema_drift_classification(self):
        parsed_log = {
            "error_type":      "SCHEMA_DRIFT",
            "missing_columns": ["postal_code"],
            "extra_columns":   ["zip_code"],
            "bad_column":      None,
            "sample_values":   [],
        }
        schema_diff = {
            "missing_columns":   ["postal_code"],
            "extra_columns":     ["zip_code"],
            "rename_candidates": [{"from": "zip_code", "to": "postal_code"}],
        }
        result = _rule_based_fallback(parsed_log, schema_diff)

        assert result["failure_category"] == "SCHEMA_DRIFT"
        assert "postal_code" in result["offending_columns"] or "zip_code" in result["offending_columns"]
        assert len(result["root_cause_explanation"]) > 20

    def test_format_encoding_classification(self):
        parsed_log = {
            "error_type":      "FORMAT_ENCODING",
            "missing_columns": [],
            "extra_columns":   [],
            "bad_column":      "order_date",
            "sample_values":   ["18-01-2024"],
        }
        schema_diff = {
            "missing_columns":   [],
            "extra_columns":     [],
            "rename_candidates": [],
        }
        result = _rule_based_fallback(parsed_log, schema_diff)

        assert result["failure_category"] == "FORMAT_ENCODING"
        assert "order_date" in result["offending_columns"]
        assert "format" in result["root_cause_explanation"].lower()
